'use strict';
// 80 authored stations: one legacy system + seven independent rule sets per chapter.
const U33 = {}, U33_CHAPTERS = [0,2,4,6,9,11,15,17,19,26];
const uRange=n=>Array.from({length:n},(_,i)=>i),uSum=a=>a.reduce((x,y)=>x+y,0),uEq=(a,b)=>JSON.stringify(a)===JSON.stringify(b),uDistinct=a=>new Set(a).size===a.length;
function uAdd(c,r,name,story,kind,build){const id='u33-'+c+'-'+r;U33[id]={c,r,name,story,kind,build};PUZZLE_NAMES[id]=name}
function uVec(labels,options,solution,rules,extra={}){return{view:'cards',labels,options:labels.map((_,i)=>Array.isArray(options[0])?options[i]:options),solution,rules,...extra}}
function uGrid(n,solution,rules,extra={}){return{view:'grid',n,labels:solution.map((_,i)=>String(i+1)),options:solution.map(()=>[0,1]),solution,rules,...extra}}
function uOrder(items,solution,rules,extra={}){return{view:'order',items,solution,rules,...extra}}
function uEdges(nodes,edges,solution,rules,extra={}){return{view:'edges',nodes,edges,options:edges.map(()=>[0,1]),solution,rules,...extra}}
function uConnected(nodes,edges,values){const seen=new Set([0]);for(let z=0;z<nodes;z++)edges.forEach(([a,b],i)=>{if(values[i]&&(seen.has(a)||seen.has(b))){seen.add(a);seen.add(b)}});return seen.size===nodes}
function uDegrees(n,edges,v){let d=Array(n).fill(0);edges.forEach(([a,b],i)=>{d[a]+=v[i];d[b]+=v[i]});return d}
function uAdj(a,b,n){return Math.abs(a%n-b%n)+Math.abs((a/n|0)-(b/n|0))===1}
function uPath(n,route,rules,extra={}){return{view:'path',n,solution:route,rules,walls:[],...extra}}
function uLatin(n){return uRange(n*n).map(i=>(i%n+(i/n|0))%n+1)}
function uPermute(n,seed){let a=uRange(n);for(let i=n-1;i>0;i--){seed=(seed*1664525+1013904223)>>>0;let j=seed%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function uModel(c,r,l){return U33['u33-'+c+'-'+r].build(l)}
// 01 — The package cannot depart until a real railway has been reconstructed.
uAdd(0,2,'Семафоры встречных поездов','Клёпка обнаруживает, что старый диспетчер оставил линию без блокировки.','semaphores',l=>{let n=4+l,sol=uRange(n).map(i=>i%3);return uVec(uRange(n).map(i=>'Сигнал '+(i+1)),[0,1,2],sol,'0 — красный, 1 — жёлтый, 2 — зелёный. Соседние сигналы различны. Восстанови сумму каждого соседнего окна и общий код линии.',{clues:sol.slice(0,-1).map((x,i)=>x+sol[i+1]),total:uSum(sol)})});
uAdd(0,3,'Расписание последнего рейса','Посылка Рин должна успеть до закрытия мокрого шлюза.','timetable',l=>{let n=4+l,sol=uRange(n).map(i=>2*i+1);return uVec(uRange(n).map(i=>'Отправление '+(i+1)),uRange(2*n+2),sol,'Назначь время каждому рейсу. Первый уходит в 1. Следующий — не раньше чем через 2. Все времена различны; соблюди общую сумму и последнее время.',{total:uSum(sol),last:sol.at(-1)})});
uAdd(0,4,'Оборванная контактная сеть','Восстанови питание вокзала, не замкнув резервный генератор.','tree',l=>{let n=4+l,edges=[...uRange(n-1).map(i=>[i,i+1]),...uRange(n-2).map(i=>[i,i+2])];return uEdges(n,edges,edges.map((_,i)=>i<n-1?1:0),'Включи ровно N−1 кабелей и соедини все станции. Ни одного замкнутого кольца: короткое замыкание уничтожит запись.',{})});
uAdd(0,5,'Вес почтового вагона','Пломба на посылке не выдержит перекоса состава.','balance',l=>{let weights=[2,3,5,7,11,13,17,19].slice(0,4+2*l),sol=weights.map((_,i)=>i%2?2:1);return uVec(weights.map(w=>'Груз '+w),[0,1,2],sol,'0 — склад, 1 — левый борт, 2 — правый. Погрузи все ящики. Два борта должны иметь заданную массу; перемещать разрешено только целые ящики.',{weights,left:uSum(weights.filter((_,i)=>sol[i]===1)),right:uSum(weights.filter((_,i)=>sol[i]===2))})});
uAdd(0,6,'Билет, разорванный дождём','Путь к Рин зашифрован стыками старого билета.','ticket',l=>{let n=4+l,order=uPermute(n,317),pieces=Array(n);order.forEach((v,i)=>pieces[v]=[i?String.fromCharCode(64+i):'НАЧАЛО',i===n-1?'КОНЕЦ':String.fromCharCode(65+i)]);return uOrder(pieces.map((a,i)=>'№'+(i+1)+' ['+a.join(' | ')+']'),order,'Собери одну ленту от НАЧАЛА до КОНЦА. Правая половина каждого обрывка должна совпасть с левой половиной следующего.',{pieces})});
uAdd(0,7,'Ложный аварийный адрес','Кто-то подменил адрес вагона с регистратором.','parity',l=>{let n=5+l,sol=uRange(n).map(i=>+(i%3===0)),checks=uRange(n).map(i=>[i,(i+1)%n,(i+3)%n]);return uVec(uRange(n).map(i=>'Адресный бит '+(i+1)),[0,1],sol,'Верни адрес по контрольным проверкам XOR: результат 1, когда включено нечётное число перечисленных битов. Дополнительно соблюди число единиц.',{checks,targets:checks.map(a=>a.reduce((v,i)=>v^sol[i],0)),ones:uSum(sol)})});
uAdd(0,8,'Манёвровый тупик','Необязательный обход позволяет забрать забытый вагон свидетелей.','shunt',l=>{let n=3+l;return{view:'dynamic',n,solution:null,rules:'Переставь вагоны из входного пути в выходной по порядку 1…N. Можно отправить первый входной вагон в тупик или сразу на выход; из тупика выходит только последний. Выход принимает только следующий номер.',input:[...uRange(n).filter(i=>i%2===0),...uRange(n).filter(i=>i%2===1).reverse()].map(i=>i+1)}});
// 03 — Snow, furnaces and a city that cannot warm every district at once.
uAdd(2,2,'Печная решётка','Жители делят оставшееся тепло по секторам, а не по приказу сверху.','latin',l=>{let n=3+l,sol=uLatin(n);return{...uGrid(n,sol,'Заполни сектора числами 1…N. В каждой строке и каждом столбце каждое число встречается один раз. Закреплённые заслонки менять нельзя.'),options:sol.map(()=>uRange(n).map(i=>i+1)),givens:uRange(n).map(i=>i*n+(i*2)%n)}});
uAdd(2,3,'Мост из углей','Переход держится лишь пока угли разгораются попеременно.','alternating',l=>{let n=4+l,route=[...uRange(n),...uRange(n-1).map(i=>(i+1)*n+n-1)],colors=uRange(n*n).map(i=>(i%n+(i/n|0))%2);return uPath(n,route,'Пройди от С до В без повторов. Цвет каждого следующего угля должен отличаться. Собери все искры ★.',{colors,checks:[route[2],route.at(-3)],goal:route.at(-1)})});
uAdd(2,4,'Холодная кладовая','Снежный квартал отдаст провизию, если не нарушить холодовую цепь.','packing',l=>{let weights=[2,3,4,5,6,7].slice(0,4+l),sol=weights.map((_,i)=>i%3),cap=uRange(3).map(j=>uSum(weights.filter((_,i)=>sol[i]===j)));return uVec(weights.map(v=>'Контейнер '+v),[0,1,2],sol,'Распредели все контейнеры между тремя камерами. Ни одна не может превышать свой предел; каждая должна быть заполнена полностью.',{weights,cap})});
uAdd(2,5,'Очередь оттаивания','Сначала освободи людей, которые смогут запустить остальные печи.','dependencies',l=>{let n=5+l,sol=uPermute(n,26),deps=sol.slice(1).map((v,i)=>[sol[i],v]);return uOrder(uRange(n).map(i=>'Заслонка '+(i+1)),sol,'Переставь заслонки в безопасный порядок. Стрелка A → B означает, что A нужно разморозить раньше B.',{deps})});
uAdd(2,6,'Замёрзшие замки','Рин оставила ключи у разных смотрителей, чтобы один не мог закрыть весь город.','keys',l=>{let n=4+l,sol=uPermute(n,937),doors=sol.map((v,i)=>[v+1,(v+i)%n+1]);return uVec(uRange(n).map(i=>'Дверь '+(i+1)),uRange(n).map(i=>i+1),sol.map(i=>i+1),'Каждый ключ используй один раз. У двери допустим один из двух номеров на бирке. Дополнительно первый и последний ключ должны дать указанную сумму.',{doors,total:sol[0]+sol.at(-1)+2})});
uAdd(2,7,'Снеговая нагрузка','Крыша над печами трескается не от холода, а от неравномерного снега.','skyline',l=>{let n=3+l,sol=uPermute(n,53).map(i=>i+1),visible=a=>a.filter((v,i)=>v>Math.max(0,...a.slice(0,i))).length;return uVec(uRange(n).map(i=>'Опора '+(i+1)),uRange(n).map(i=>i+1),sol,'Распредели высоты 1…N без повторов. Слева и справа видны только опоры выше всех предыдущих; соблюди обе видимости и высоту центральной опоры.',{left:visible(sol),right:visible([...sol].reverse()),middle:sol[n>>1]})});
uAdd(2,8,'Пар не должен вернуться','Скрытая котельная может согреть запасной вагон.','flow',l=>{let n=4+l,edges=[...uRange(n-1).map(i=>[i,i+1]),[0,2],[1,n-1]],sol=edges.map((_,i)=>i<n-1?2:0);return{...uEdges(n,edges,sol,'На каждом направленном участке выставь поток 0, 1 или 2. Из истока выходит 2, в сток входит 2, в остальных узлах приход равен расходу. Пар нельзя отправить по всем трубам сразу.'),options:edges.map(()=>[0,1,2]),budget:2*(n-1)}});
// 05 — A carnival whose theatre was built to turn people into puppets.
uAdd(4,2,'Королевы прожекторов','Артистов нельзя осветить двумя прожекторами одновременно.','queens',l=>{let n=[4,5,6][l],sol= n===4?[1,3,0,2]:n===5?[0,2,4,1,3]:[1,3,5,0,2,4];return uVec(uRange(n).map(i=>'Ряд сцены '+(i+1)),uRange(n).map(i=>i+1),sol.map(i=>i+1),'В каждом ряду поставь один прожектор. Они не должны видеть друг друга по столбцам и по обеим диагоналям.',{n})});
uAdd(4,3,'Декорация с одной стороны','Уведи тяжёлый ящик со сцены: его можно толкать, но нельзя тянуть.','sokoban',l=>{let n=5+l,walls=[0,n-1,n*(n-1),n*n-1];return{view:'dynamic',n,walls,player:n+1,box:n+2,goal:n*(n-2)+n-2,rules:'Доставь ящик □ на сценическую метку ◆. Герой ходит стрелками. Ящик можно только толкать: не загоняй его к стене. Отмена U возвращает и героя, и ящик.'}});
uAdd(4,4,'Башня противовесов','Подъёмник сцены уравновешен дисками, каждый из которых тяжелее предыдущего.','hanoi',l=>({view:'dynamic',n:3+l,rules:'Перенеси все диски с левой стойки на правую. За ход переносится верхний диск; большой нельзя класть на меньший.'}));
uAdd(4,5,'Маски лжецов','Труппа говорит правду лишь в той маске, которую не выбирала сама.','liars',l=>{let n=4+l,sol=uRange(n).map(i=>i%2),claims=uRange(n).map(i=>({who:(i+1)%n,says:sol[i]?sol[(i+1)%n]:1-sol[(i+1)%n]}));return uVec(uRange(n).map(i=>'Артист '+(i+1)),[0,1],sol,'0 — лжец, 1 — правдивый. Правдивый произносит верное утверждение, лжец — неверное. Известно также, сколько правдивых в труппе.',{claims,count:uSum(sol)})});
uAdd(4,6,'Партнёры без отражений','В финальном танце никто не должен получить собственную маску.','derangement',l=>{let n=4+l,sol=uRange(n).map(i=>(i+1)%n+1);return uVec(uRange(n).map(i=>'Танцор '+(i+1)),uRange(n).map(i=>i+1),sol,'Раздай все маски один раз. Собственный номер запрещён. Пары танцоров тоже не могут просто обменяться своими масками; должна получиться одна общая цепь.',{n})});
uAdd(4,7,'Репетиция без дирижёра','Музыканты должны восстановить ритм по разным партиям, не подчиняясь одному голосу.','rhythm',l=>{let n=5+l,sol=uRange(n).map(i=>i%3+1);return uVec(uRange(n).map(i=>'Доля '+(i+1)),[1,2,3],sol,'Восстанови длительности нот. Суммы соседних пар указаны; всего тактовый круг имеет заданную длину. Первая и последняя ноты различны.',{pairs:sol.slice(0,-1).map((v,i)=>v+sol[i+1]),total:uSum(sol)})});
uAdd(4,8,'Шестерни кулис','Кулисы заклинило: соседние оси связаны разными передаточными числами.','gears',l=>{let n=4+l,sol=uRange(n).map(i=>i%3),target=uRange(n).map(i=>(sol[i]+2*sol[(i+n-1)%n])%5);return{...uVec(uRange(n).map(i=>'Ось '+(i+1)),uRange(5),sol,'Нажатие на ось добавляет ей 1, а следующей — 2 по кругу 0…4. Совмести все значения с образцом. Повторять цикл разрешено.'),view:'gears',target}});
// 07 — The archive contains evidence, not a row of interchangeable terminals.
uAdd(6,2,'Письмо с заменённым алфавитом','Расшифруй первое сообщение Рин до того, как цензор узнает его почерк.','cipher',l=>{let n=4+l,sol=uPermute(n,83),encoded=[0,1,2,0,3,1,...(l?[n-1,2]:[])],word=encoded.map(i=>String.fromCharCode(1040+sol[i])).join('');return uVec(uRange(n).map(i=>'Символ '+String.fromCharCode(945+i)),uRange(n).map(i=>String.fromCharCode(1040+i)),sol.map(i=>String.fromCharCode(1040+i)),'Каждый символ заменяет одну букву, разные символы — разные буквы. Сравни зашифрованную строку с восстановленной копией из реестра.',{encoded,word})});
uAdd(6,3,'Каталог с запретными полками','Запретные книги спрятаны так, чтобы любой квартал мог собрать свой архив.','sudoku',l=>{let n=4,sol=uRange(16).map(i=>(i%4+(i/4|0)*2+(i/8|0))%4+1);return{...uGrid(n,sol,'Заполни числами 1…4. В строке, столбце и каждом блоке 2×2 все числа различны. На сложной сложности закреплено меньше страниц.'),options:sol.map(()=>[1,2,3,4]),givens:uPermute(16,16).slice(0,[9,6,3][l])}});
uAdd(6,4,'Мосты между показаниями','Показания связаны нитями: ни один свидетель не должен остаться отдельно.','bridges',l=>{let n=4+l,edges=[...uRange(n-1).map(i=>[i,i+1]),[0,n-1]],sol=edges.map((_,i)=>i===n-1?0:1+(i%2));return{...uEdges(n,edges,sol,'У каждого острова указано число мостов. Между парой можно построить 0, 1 или 2. Все острова должны быть связаны.'),options:edges.map(()=>[0,1,2]),degrees:uDegrees(n,edges,sol)}});
uAdd(6,5,'Даты, которых не было','Установи порядок событий: официальный календарь переписали после катастрофы.','chronology',l=>{let n=4+l,sol=uPermute(n,74),positions=Array(n);sol.forEach((v,i)=>positions[v]=i);let distances=sol.slice(0,-2).map((v,i)=>[v,sol[i+2],2]);return uOrder(uRange(n).map(i=>'Запись '+(i+1)),sol,'Между отмеченными записями должно быть ровно заданное расстояние в позициях. Восстанови полный порядок от старой к новой.',{distances,first:sol[0],last:sol.at(-1)})});
uAdd(6,6,'Прозрачные страницы','Цензор записал карту на нескольких прозрачных листах.','overlay',l=>{let n=3+l,layers=uRange(3).map(k=>uRange(n*n).map(i=>+((i*(k+2)+k)%5<2))),sol=[1,2,3],rotate=(a,t)=>uRange(n*n).map(i=>{let x=i%n,y=i/n|0;for(let j=0;j<t;j++)[x,y]=[y,n-1-x];return a[y*n+x]}),target=uRange(n*n).map(i=>rotate(layers[0],1)[i]^rotate(layers[1],2)[i]^rotate(layers[2],3)[i]);return uVec(['Лист A','Лист B','Лист C'],[0,1,2,3],sol,'Поворачивай листы на 0, 90, 180 или 270 градусов. Два чёрных поля гасят друг друга (XOR). Собери целевой оттиск.',{n,layers,target})});
uAdd(6,7,'Допрос без обвинения','Найди, какой вагон видел каждый свидетель. Их показания неполны, но не случайны.','witness',l=>{let n=4+l,sol=uPermute(n,109).map(i=>i+1);return uVec(uRange(n).map(i=>'Свидетель '+(i+1)),uRange(n).map(i=>i+1),sol,'Каждый видел свой вагон, номера не повторяются. Соблюди сравнения показаний и сумму двух крайних свидетелей.',{comparisons:sol.slice(0,-1).map((v,i)=>[i,i+1,v<sol[i+1]?'<':'>']),sum:sol[0]+sol.at(-1),anchor:sol[n>>1]})});
uAdd(6,8,'Повреждённая контрольная запись','Сохрани доказательство, даже если одна копия оказалась испорчена.','checksum',l=>{let n=4+l,sol=uRange(n).map(i=>(i*3+2)%7);return uVec(uRange(n).map(i=>'Байт '+(i+1)),uRange(7),sol,'Восстанови байты 0…6 по сумме, взвешенной сумме и соседним разностям по модулю 7. Все контрольные данные видны.',{diff:sol.slice(0,-1).map((v,i)=>(sol[i+1]-v+7)%7),sum:uSum(sol),weighted:uSum(sol.map((v,i)=>v*(i+1)))})});
// 10 — Glass storm: light, topology and phase instead of another collecting loop.
uAdd(9,2,'Призма без белого света','Слишком яркий луч разбудит глаз бури. Раздели его, не потеряв цвет.','colors',l=>{let n=4+l,sol=uRange(n).map(i=>i%7+1),targets=sol.slice(0,-1).map((v,i)=>v|sol[i+1]);return uVec(uRange(n).map(i=>'Фильтр '+(i+1)),uRange(8),sol,'Цвет — битовая смесь: красный 1, зелёный 2, синий 4. Совместный луч соседних фильтров даёт OR. Соблюди все смеси и суммарное число цветовых компонентов.',{targets,components:uSum(sol.map(v=>v.toString(2).split('1').length-1))})});
uAdd(9,3,'Лидар невидимых осколков','Расставь метки осколков, которые прячутся в прозрачном полу.','mines',l=>{let n=4+l,sol=uRange(n*n).map(i=>+(i%7===3)),known=uRange(n*n).filter(i=>!sol[i]&&i%2===0),counts=uRange(n*n).map(i=>uRange(n*n).filter(j=>j!==i&&Math.abs(i%n-j%n)<=1&&Math.abs((i/n|0)-(j/n|0))<=1).reduce((v,j)=>v+sol[j],0));return uGrid(n,sol,'Отметь все скрытые осколки ■. Число показывает осколки в восьми соседних клетках. Числовые клетки безопасны; общее число осколков известно.',{known,counts,total:uSum(sol)})});
uAdd(9,4,'Односторонние порывы','Ветер пропускает поезд только в одну сторону, но следы Рин показывают выход.','directed',l=>{let n=4+l,route=[...uRange(n),...uRange(n-1).map(i=>(i+1)*n+n-1)],dirs=uRange(n*n).map(i=>i%n===n-1?n:1);return uPath(n,route,'Иди от С к В. Выходить из клетки можно только по её стрелке; пройди через маяки ★. Назад можно вернуться только отменой.',{dirs,checks:[n-2,(n-2)*n+n-1],goal:n*n-1})});
uAdd(9,5,'Нити радуги','Свяжи берега шторма, не позволив световым нитям пересечься.','matching',l=>{let n=4+l,sol=uRange(n).map(i=>i+1);return uVec(uRange(n).map(i=>'Левый порт '+(i+1)),uRange(n).map(i=>i+1),sol,'Левые и правые порты расположены сверху вниз. Каждый правый используй один раз; нити не пересекаются. Некоторые порты требуют чётного либо нечётного номера.',{parities:sol.map(v=>v%2)})});
uAdd(9,6,'Громоотвод','Отключи минимальное число проводов, чтобы молния не дошла до поезда.','cut',l=>{let n=4+l,edges=[...uRange(n-1).map(i=>[i,i+1]),[0,2],[1,n-1]],sol=edges.map(([a,b])=>+(a===0||b===0));return uEdges(n,edges,sol,'1 — разрезанный провод. Изолируй узел 1 от N, разрезав ровно два провода. Остальные провода остаются целыми.',{budget:2})});
uAdd(9,7,'Частота стеклянных колоколов','Три колокола должны встретиться в одной фазе, иначе стекло разрежет путь.','phase',l=>{let periods=[4,5,7].slice(0,l===0?2:3),time=[13,37,83][l];return uVec(['Общий такт'],uRange([30,80,140][l]),[time],'Найди такт, в котором каждый колокол имеет указанный остаток. Каждый колокол считает по своему периоду.',{periods,remainders:periods.map(v=>time%v)})});
uAdd(9,8,'Кольцо спокойного воздуха','Замкни защитный контур вокруг поезда, не оставив лишних ответвлений.','loop',l=>{let n=4+l,edges=[...uRange(n).map(i=>[i,(i+1)%n]),[0,2],[1,3]],sol=edges.map((_,i)=>+(i<n));return uEdges(n,edges,sol,'Собери один связный цикл. Каждый узел должен иметь ровно два ребра. Запрещённые хорды отмечены в протоколе.',{forbidden:[n,n+1]})});
// 12 — Inside a living body, engineering choices have a biological cost.
uAdd(11,2,'Нервные ворота','Пастырь реагирует на электрический язык, а не на обещания.','gates',l=>{let n=4+l,sol=uRange(n).map(i=>i%2),gates=uRange(n).map(i=>({a:i,b:(i+1)%n,op:['AND','OR','XOR'][i%3]})),evalg=(g,v)=>g.op==='AND'?(v[g.a]&v[g.b]):g.op==='OR'?(v[g.a]|v[g.b]):(v[g.a]^v[g.b]);return uVec(uRange(n).map(i=>'Нейрон '+(i+1)),[0,1],sol,'Установи входы логической сети. Каждые ворота должны дать свой результат; число активных нейронов также фиксировано.',{gates,outputs:gates.map(g=>evalg(g,sol)),count:uSum(sol)})});
uAdd(11,3,'Один вдох на двоих','Дойди до клапана, сохранив достаточно воздуха для обратного сигнала.','breath',l=>{let n=4+l,route=[...uRange(n),...uRange(n-1).map(i=>(i+1)*n+n-1)];return uPath(n,route,'Каждый шаг расходует 1 воздух. На клетке O запас восстанавливается до максимума. Нельзя идти с нулём; приди к выходу с запасом не меньше 1.',{air:n+1,refills:[n-1],goal:n*n-1,checks:[]})});
uAdd(11,4,'Перевозчик живого груза','Хищник, корм и пациент не могут ждать на одном берегу без присмотра.','river',l=>({view:'dynamic',n:3+l,rules:'Перевези всех на правый берег. Лодка берёт одного пассажира или идёт пустой. Без перевозчика нельзя оставлять рядом пары, указанные ниже. Соседние номера 1–2, 2–3 запрещены; остальные совместимы.',conflicts:[[0,1],[1,2]]}));
uAdd(11,5,'Пик давления','Важно не только итоговое давление, но и ни разу не порвать сосуды по пути.','pressure',l=>{let vals=[4,-3,5,-2,3,-4,2].slice(0,5+l),sol=uRange(vals.length),start=4,peak=4,low=4;for(let v of vals){start+=v;peak=Math.max(peak,start);low=Math.min(low,start)}return uOrder(vals.map((v,i)=>'Клапан '+(i+1)+' ('+(v>=0?'+':'')+v+')'),sol,'Начальное давление 4. Открой каждый клапан один раз; давление после каждого открытия должно оставаться в безопасном диапазоне. После положительного клапана нужен отрицательный, пока они есть.',{vals,min:Math.min(1,low),max:peak})});
uAdd(11,6,'Пропорция кислорода','Смесь должна поддержать живой материк, а не просто заполнить баллон.','mixture',l=>{let n=3+l,sol=uRange(n).map(i=>i+1),oxygen=[1,3,2,5,4].slice(0,n),toxin=[2,0,1,0,1].slice(0,n);return uVec(oxygen.map((v,i)=>'Смесь '+(i+1)+' O:'+v+' / примесь:'+toxin[i]),uRange(n+2),sol,'Выставь целое число доз каждого состава. Совпасть должны объём, кислород и количество примеси. Подбор одной суммы недостаточен.',{oxygen,toxin,volume:uSum(sol),air:uSum(sol.map((v,i)=>v*oxygen[i])),waste:uSum(sol.map((v,i)=>v*toxin[i]))})});
uAdd(11,7,'Парные заплаты','Закрой разрывы попарно, не накладывая заплаты одна на другую.','domino',l=>{let n=4,rows=2+l,sol=uRange(n*rows).map(i=>(i/2|0)+1);return{...uGrid(n,sol,'Назначь каждой клетке номер заплаты. Каждый номер встречается ровно два раза, его клетки должны соседствовать стороной. Серебряные клетки закреплены.'),rows,options:sol.map(()=>uRange(n*rows/2).map(i=>i+1)),givens:uRange(rows).map(i=>i*n)}});
uAdd(11,8,'Один живой импульс','Оставь только один сигнал в повреждённой цепи.','peg',l=>({view:'dynamic',n:5+2*l,rules:'Импульс ● перескакивает через соседний импульс в пустую клетку, съедая перепрыгнутый. Оставь ровно один импульс. Доступные прыжки показаны кнопками.',line:true}));
// 16 — The station of yesterday changes causality, not only the clock decoration.
uAdd(15,2,'Письма в прошлое','Измени причины так, чтобы вчерашние письма не уничтожили сегодняшних свидетелей.','causality',l=>{let n=4+l,sol=uRange(n).map(i=>i%2),links=uRange(n).map(i=>[i,(i+2)%n]);return uVec(uRange(n).map(i=>'Вчерашнее письмо '+(i+1)),[0,1],sol,'Письмо i создаёт сегодняшний след i XOR след двух позиций назад. Восстанови образец следов, сохранив заданное число отправленных писем.',{links,target:links.map(([a,b])=>sol[a]^sol[b]),count:uSum(sol)})});
uAdd(15,3,'Часы с неверными стрелками','Трое часовщиков помнят разные часы катастрофы.','clock',l=>{let n=3+l,mods=[5,7,9,11,13].slice(0,n),sol=uRange(n).map(i=>(i*2+1)%mods[i]);return uVec(mods.map(v=>'Циферблат / '+v),mods.map(v=>uRange(v)),sol,'Поворот стрелки выражен остатком. Разности соседних стрелок и сумма всех стрелок известны; первая стрелка закреплена показанием свидетеля.',{diff:sol.slice(0,-1).map((v,i)=>sol[i+1]-v),total:uSum(sol),first:sol[0]})});
uAdd(15,4,'Перевёрнутая плёнка','Кадры нельзя переставить по одному: барабан переворачивает целый фрагмент.','reversal',l=>({view:'dynamic',n:4+l,rules:'Верни кадры в порядок 1…N. Выбери два конца фрагмента: весь фрагмент переворачивается. Указание одного конца ещё не считается ходом.'}));
uAdd(15,5,'Контрольная точка вчера','Сначала открой путь в прошлом; затем верни героя, не отменяя сделанный выбор.','rewind',l=>{let n=4+l;return{view:'dynamic',n,rules:'Иди к рычагу Р в верхнем правом углу, включи его, затем нажми «Вернуть героя». Рычаг сохраняет положение. Теперь можно пройти сквозь закрытый ранее шлюз к В. До перемотки выход не принимает героя.',goal:n*n-1,lever:n-1}});
uAdd(15,6,'День без названия','Найди дни встреч по неполному календарю, а не по официальной дате.','calendar',l=>{let n=4+l,sol=uRange(n).map(i=>2*i+1);return uVec(uRange(n).map(i=>'Встреча '+(i+1)),uRange(2*n+2).map(i=>i+1),sol,'Все встречи в разные дни. У каждой известен остаток дня по неделе из 3 дней. Разности между встречами фиксированы; самая ранняя — в день 1.',{mods:sol.map(v=>v%3),gaps:sol.slice(0,-1).map((v,i)=>sol[i+1]-v)})});
uAdd(15,7,'Две несовместимые версии','Ни одна из двух хроник не полна: найди переключатели, которые удовлетворяют обеим.','parallel',l=>{let n=4+l,sol=uRange(n).map(i=>i%2),clauses=uRange(n).map(i=>[i,(i+1)%n,sol[i]===1]);return uVec(uRange(n).map(i=>'Событие '+(i+1)),[0,1],sol,'Первая хроника задаёт OR соседних событий, вторая — AND. Совмести обе, причём число случившихся событий фиксировано.',{ors:sol.map((v,i)=>v|sol[(i+1)%n]),ands:sol.map((v,i)=>v&sol[(i+2)%n]),count:uSum(sol)})});
uAdd(15,8,'Одна дорога через все вчера','Запиши путь так, чтобы ни одна версия станции не осталась за кадром.','hamilton',l=>{let n=3+l,route=[];for(let y=0;y<n;y++)for(let j=0;j<n;j++)route.push(y*n+(y%2?n-1-j:j));return uPath(n,route,'Посети все клетки ровно один раз. Начни в С, закончи в В. Дополнительно пройди отмеченные кадры по порядку.',{goal:route.at(-1),checks:[route[n],route[2*n]]})});
// 18 — Ice and depth: information, inertia and limited oxygen.
uAdd(17,2,'Сонар затонувших вагонов','У подводного депо нужно отличить корпус вагона от обломков.','ships',l=>{let n=4+l,sol=uRange(n*n).map(i=>+((i/n|0)%3===0&&i%n<2));return uGrid(n,sol,'Отметь затонувшие секции. Выполни суммы строк и столбцов. Разные корабли не касаются даже углами; каждый корабль прямой и длиной 2.',{rowsums:uRange(n).map(y=>uSum(sol.slice(y*n,(y+1)*n))),colsums:uRange(n).map(x=>uSum(uRange(n).map(y=>sol[y*n+x]))),fleet:uSum(sol)/2})});
uAdd(17,3,'Запутавшийся страховочный трос','Поменяй положения узлов, не перерезая страховку экипажа.','untangle',l=>{let n=4+l,sol=uPermute(n,3),edges=uRange(n-1).map(i=>[sol[i],sol[i+1]]);return uOrder(uRange(n).map(i=>'Узел '+(i+1)),sol,'Уложи узлы на береговой линии так, чтобы каждый отрезок троса соединял соседние позиции. Трос не должен перескакивать через другой узел.',{edges})});
uAdd(17,4,'Код гермодвери','Старая дверь отвечает только числом точных и переставленных знаков.','mastermind',l=>{let n=3+l,sol=uRange(n).map(i=>(i*2+1)%6),guesses=uRange(n+1).map(k=>uRange(n).map(i=>(i+k)%6));return uVec(uRange(n).map(i=>'Разряд '+(i+1)),uRange(6),sol,'Восстанови код по журналу проб. «На месте» — правильный знак и позиция; «не там» — правильный знак в другой позиции. Повторы разрешены.',{guesses,feedback:guesses.map(g=>uMaster(sol,g))})});
uAdd(17,5,'Поворот ледяных плит','Между трещинами нужно не пробежать, а собрать непрерывный проход.','tiles',l=>{let n=3+l,sol=uRange(n*n).map(i=>i%2),target=uRange(n*n).map(i=>sol[i]^(i%n?sol[i-1]:0));return uVec(uRange(n*n).map(i=>'Плита '+(i+1)),[0,1],sol,'Каждая плита имеет две стороны. Шов между плитой и её левым соседом открыт, если стороны различаются. У первого столбца слева постоянный 0. Собери весь образец швов.',{n,target})});
uAdd(17,6,'Кислород для спасателей','Не все инструменты поместятся в дыхательную капсулу.','knapsack',l=>{let w=[2,3,4,6,7,8,9].slice(0,5+l),v=[3,5,6,10,11,13,15].slice(0,5+l),best=0,solution=[];for(let b=0;b<1<<w.length;b++){let a=w.map((_,i)=>b>>i&1),cost=uSum(a.map((x,i)=>x*w[i])),val=uSum(a.map((x,i)=>x*v[i]));if(cost<=10+4*l&&val>best){best=val;solution=a}}return uVec(w.map((x,i)=>'Груз '+(i+1)+' · O '+x+' · польза '+v[i]),[0,1],solution,'Выбери спасательный набор. Расход кислорода не превышает лимит, польза — не меньше необходимой. Не нужно брать всё.',{w,v,cap:10+4*l,target:best})});
uAdd(17,7,'Магнитный подъём','Спаси металлический регистратор, не притягивая его к герою сквозь стены.','magnet',l=>({view:'dynamic',n:5+l,player:0,box:2,goal:(5+l)*(5+l)-2,rules:'Герой ходит стрелками. Кнопка «Притянуть» сдвигает ящик на одну клетку к герою, если они на одной строке или столбце. Не тяни ящик на себя: клетка героя должна остаться свободной. Доставь ящик на ◆.'}));
uAdd(17,8,'Гаснущая ледяная решётка','Северные огни скрывают запасной шлюз.','lights',l=>{let n=3+l,press=uRange(n*n).filter(i=>i%4===1),initial=Array(n*n).fill(0);for(const i of press)for(const j of uRange(n*n))if(i===j||uAdj(i,j,n))initial[j]^=1;return{...uGrid(n,Array(n*n).fill(0),'Нажатие меняет клетку и четырёх соседей по сторонам. Погаси всю решётку; край не соединяется с противоположным краем.'),view:'lights',initial,proof:press.map(i=>({i}))}});
// 20 — The engine is a set of different interdependent systems.
uAdd(19,2,'Трубопровод под кожей','Поверни патрубки так, чтобы сердце двигателя получило охлаждение.','pipes',l=>{let n=3+l,sol=uRange(n*n).map(i=>i%n===n-1?2:1);return{...uGrid(n,sol,'Поверни стрелки труб. Из С поток следует стрелке каждой клетки. Он должен пройти все отмеченные клапаны и выйти в В; тупик и цикл запрещены.'),options:sol.map(()=>[0,1,2,3]),goal:n*n-1,checks:[n-1,n*(n-1)],n,solution:uRange(n*n).map(i=>(i/n|0)%2===0?(i%n===n-1?2:1):(i%n===0?2:3))}});
uAdd(19,3,'Предохранители без соседей','Двигатель выдержит нагрузку, если не перегреть соседние секции.','fuses',l=>{let n=6+2*l,w=uRange(n).map(i=>i+2),sol=w.map((_,i)=>+(i%3===0));return uVec(w.map(v=>'Предохранитель '+v),[0,1],sol,'Включённые предохранители не соседствуют, включая первый и последний. Соблюди количество включённых и общую мощность.',{weights:w,count:uSum(sol),target:uSum(sol.map((v,i)=>v*w[i]))})});
uAdd(19,4,'Обход ремонтника','Проверь каждую перемычку ровно один раз, не возвращаясь по уже пройденному кабелю.','euler',l=>{let n=6+l,edges=uRange(n).map(i=>[i,(i+1)%n]),sol=[...uRange(n),0];if(l>0){edges.push([0,2],[2,4],[4,0]);sol.push(2,4,0)}return{view:'graphpath',nodes:n,edges,solution:sol,rules:'Начни в узле 1. Пройди каждое ребро ровно один раз и вернись в начало. Узлы разрешено посещать повторно, рёбра — нет.'}});
uAdd(19,5,'Панели аварийного корпуса','Закрой корпус готовыми пластинами: разрезать их нельзя.','cover',l=>{let n=4,rows=2+l,placements=[];for(let y=0;y<rows;y++)for(let x=0;x<4;x+=2)placements.push([y*4+x,y*4+x+1]);for(let y=0;y<rows-1;y++)for(let x=0;x<4;x++)placements.push([y*4+x,(y+1)*4+x]);return uVec(placements.map(a=>'Пластина ['+a.map(i=>i+1).join(', ')+']'),[0,1],placements.map((_,i)=>+(i<rows*2)),'Выбери готовые пластины. Каждая клетка корпуса должна оказаться закрыта ровно одной пластиной — без дыр и перекрытий.',{n,rows,placements})});
uAdd(19,6,'Цвета независимых цепей','Соседние узлы не могут пользоваться одной аварийной фазой.','coloring',l=>{let n=4+l,edges=uRange(n).map(i=>[i,(i+1)%n]),sol=uRange(n).map(i=>i%2+1);if(n%2)sol[n-1]=3;return{...uEdges(n,edges,[],''),...uVec(uRange(n).map(i=>'Узел '+(i+1)),[1,2,3],sol,'Раскрась узлы тремя фазами. На каждом кабеле цвета концов различны. Не превышай число переключателей третьей фазы.',{edges,max3:l===1?1:0})}});
uAdd(19,7,'Аккумулятор команд','Порядок операций важнее их суммы: двигатель считает последовательно.','accumulator',l=>{let ops=['+3','×2','−1','+4',...(l>0?['×3']:[]),...(l>1?['−5']:[])],sol=uPermute(ops.length,492),calc=a=>a.reduce((v,i)=>ops[i][0]==='×'?v*+ops[i].slice(1):ops[i][0]==='−'?v-+ops[i].slice(1):v+ +ops[i].slice(1),1);return uOrder(ops,sol,'Начни с 1. Используй каждую команду ровно один раз, выполняя слева направо, без приоритета умножения. Получи указанное значение.',{target:calc(sol)})});
uAdd(19,8,'Независимый резерв','Резерв должен пережить отказ любого одного кабеля.','redundancy',l=>{let n=4+l,edges=[...uRange(n).map(i=>[i,(i+1)%n]),...uRange(n-2).map(i=>[i,i+2])];return uEdges(n,edges,edges.map((_,i)=>+(i<n)),'Построй сеть из ровно N кабелей, которая останется связной при удалении любого одного включённого кабеля. Простое дерево больше не подходит.',{})});
// 27 — Rails become bridges: solve a small society, not a machine checklist.
